import{_ as t,a as s}from"./chunks/printer-bars.CnFg_LrS.js";import{_ as r,o as a,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse(`{"title":"Imprimante – Imprimante et cartouches","description":"Ensemble de widgets (widgetset) autonome pour imprimante, affichant l'état et jusqu'à six cartouches réparties automatiquement de manière uniforme.","frontmatter":{"title":"Imprimante – Imprimante et cartouches","description":"Ensemble de widgets (widgetset) autonome pour imprimante, affichant l'état et jusqu'à six cartouches réparties automatiquement de manière uniforme."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/printer.md","filePath":"fr/projects/grafik-visual-studio/printer.md","lastUpdated":1793127012000}`),o={name:"fr/projects/grafik-visual-studio/printer.md"};function l(u,e,d,c,p,m){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="printer" tabindex="-1">Imprimante <a class="header-anchor" href="#printer" aria-label="Permalink to &quot;Imprimante {#printer}&quot;">​</a></h1><p>À partir de la version <strong>Studio 0.1.273</strong>, l&#39;option est accessible via <strong>Propriétés → WIDGET → Cartouches → Style → Cartouches / Barres</strong>. Le mode <strong>Cartouches</strong> affiche les graphismes habituels côte à côte ; le mode <strong>Barres</strong> affiche 1 à 6 lignes comprenant le nom, un indicateur de niveau horizontal et un pourcentage. Les entités, les couleurs et le seuil d&#39;alerte s&#39;appliquent aux deux styles. Les valeurs manquantes sont représentées par <strong>—</strong> ; l&#39;ancienne option « Toner » est désormais intégrée sous forme de barres. Le paramètre de taille (pleine/demi) des cartouches ne s&#39;applique qu&#39;aux graphismes de type « cartouche ». Le <strong>pack Imprimante 0.1.1</strong> contient cette option corrigée ; les instances existantes basées sur <strong>0.1.0-Pakete</strong> restent compatibles avec la version mise à jour de Studio.</p><p><strong>Printer 0.1.1</strong> est un ensemble de widgets externe créé par <strong>rockbaer2007</strong>. Pour utiliser les styles présentés ici, la version <strong>Grafik Visual Studio 0.1.273 (ou ultérieure)</strong> est requise. Il affiche une imprimante avec son état actuel ainsi que <strong>1 à 6 niveaux d&#39;encre ou de toner</strong>, représentés au choix par des graphismes de cartouches ou par des barres horizontales.</p><h3 id="stil-patronen" tabindex="-1">Style : Cartouches <a class="header-anchor" href="#stil-patronen" aria-label="Permalink to &quot;Style : Cartouches {#stil-patronen}&quot;">​</a></h3><p>L&#39;image montre l&#39;interface en cours d&#39;exécution (runtime) avec des données de test.</p><p><img src="'+t+'" alt="Imprimante avec six cartouches et un indicateur d&#39;alerte"></p><h3 id="stil-balken" tabindex="-1">Style : Barres <a class="header-anchor" href="#stil-balken" aria-label="Permalink to &quot;Style : Barres {#stil-balken}&quot;">​</a></h3><p>Sous <strong>Propriétés → WIDGET → Cartouches → Style</strong>, sélectionnez l&#39;option <strong>Barres</strong>. L&#39;image d&#39;exécution (runtime) suivante présente six niveaux de remplissage avec des données de test : le niveau <strong>Jaune (18 %)</strong> est inférieur au seuil d&#39;alerte de 20 % et apparaît donc mis en évidence. Pour la couleur <strong>Gris</strong>, aucune mesure n&#39;est disponible ; la barre est hachurée et affiche <strong>—</strong> au lieu d&#39;une valeur en pourcentage arbitraire.</p><p><img src="'+s+'" alt="Affichage de type « barres » pour imprimante, avec six niveaux de remplissage, une alerte pour le jaune et un niveau inconnu pour le gris"></p><h2 id="originalprojekt" tabindex="-1">Projet original <a class="header-anchor" href="#originalprojekt" aria-label="Permalink to &quot;Projet original {#originalprojekt}&quot;">​</a></h2><p>Ce composant s&#39;inspire de la carte <a href="https://github.com/ADNPolymerase/ha-printer-card" target="_blank" rel="noreferrer">HA Printer Card d&#39;ADNPolymerase</a>, publiée sous <a href="https://github.com/ADNPolymerase/ha-printer-card/blob/main/LICENSE" target="_blank" rel="noreferrer">licence MIT</a>. L&#39;original est une carte Lovelace. « Printer » utilise son propre dessin SVG, son propre moteur de rendu (Studio Renderer) et des entités Home Assistant spécifiquement sélectionnées. Le code et les graphismes originaux ne sont pas intégrés. Il fait partie d&#39;un ensemble distinct dans la palette, et non de la catégorie « Industrial ».</p><h2 id="installieren" tabindex="-1">Installation <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installation {#installieren}&quot;">​</a></h2><ol><li>Mettez à jour Grafik Visual Studio vers la version <strong>0.1.273 ou ultérieure</strong>.</li><li>Téléchargez le fichier <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/ha_grafik_visual_studio/packages/printer/ugso.printer.wg" target="_blank" rel="noreferrer">ugso.printer.wg</a>.</li><li>Installez-le via <strong>Paramètres → Packs de widgets → Local</strong>.</li><li>Insérez l&#39;élément <strong>Printer → Imprimante</strong> depuis la palette, puis sélectionnez les entités correspondant à l&#39;état et aux niveaux de remplissage à l&#39;aide du bouton <strong>…</strong>.</li></ol><p>Le pack contient une définition déclarative du widget, une icône dédiée pour la palette, une documentation et la licence MIT. Il ne contient aucun code exécutable. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/printer" target="_blank" rel="noreferrer">Code source et documentation du pack</a>.</p><h2 id="einstellungen" tabindex="-1">Paramètres <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Paramètres {#einstellungen}&quot;">​</a></h2><p>À partir de la version <strong>0.1.270</strong> du studio, les sections <strong>CSS Font &amp; Text</strong> (Police et texte), <strong>CSS Hintergrund</strong> (Arrière-plan), <strong>CSS Ränder</strong> (Bordures) et <strong>CSS Schatten und Abstand</strong> (Ombres et espacements) sont disponibles sous <strong>Propriétés → WIDGET</strong>, en complément de la section <strong>CSS Allgemein</strong> (CSS général). Ces nouveaux groupes sont désactivés par défaut. Activez-les en cochant la case correspondante pour configurer la police, l&#39;arrière-plan (ou l&#39;image), la couleur, l&#39;épaisseur et le style des bordures, le rayon des angles (<strong>0 = angles vifs</strong>), ainsi que les ombres et les espacements. Le CSS s&#39;applique à la carte d&#39;imprimante visible, et non à l&#39;arrière-plan situé derrière celle-ci. Les couleurs relatives à l&#39;état et aux cartouches conservent leurs propres paramètres. Continuez à utiliser le paquet existant.</p><table tabindex="0"><thead><tr><th>Section</th><th>Paramètre</th></tr></thead><tbody><tr><td>Imprimante</td><td>Nom, entité d&#39;état, modèle : <code>mfp</code> (multifonction), <code>inkjet</code> (jet d&#39;encre) ou <code>office</code> (imprimante de bureau).</td></tr><tr><td>Cartouches</td><td>Nombre (<strong>1–6</strong>), <strong>Style → Cartouches / Barres</strong>, seuil d&#39;alerte (<strong>0–100 %</strong>, valeur par défaut : <strong>20 %</strong>).</td></tr><tr><td>Cartouche 1–6</td><td>Entité dédiée au niveau de remplissage (en pourcentage), libellé et couleur. Les N premières entrées sont actives. Les liaisons configurées pour des entrées ultérieures restent enregistrées, mais ne sont sollicitées que si le nombre total d&#39;entrées est augmenté.</td></tr><tr><td>Message d&#39;état</td><td>Peut être masqué. Entité distincte facultative ; sinon, utilise <code>state_message</code> ou <code>state_reason</code> de l&#39;entité imprimante.</td></tr><tr><td>Valeurs supplémentaires</td><td>Entités facultatives pour la puissance (consommation) et le compteur de pages.</td></tr><tr><td>Couleurs et dimensions</td><td>Couleurs de l&#39;arrière-plan, de la police et de l&#39;état de l&#39;imprimante. Dimensions par défaut : <strong>480 × 440 px</strong> ; dimensions minimales : <strong>240 × 280 px</strong>.</td></tr></tbody></table><p>Le nombre d&#39;éléments détermine la répartition ; il n&#39;est pas nécessaire de définir manuellement les positions X pour chaque cartouche. En cas d&#39;espace restreint, les noms longs sont tronqués. Les noms complets et les valeurs sont affichés dans une info-bulle. À partir de la version <strong>Studio 0.1.263</strong>, seules les cartouches sélectionnées apparaissent dans les propriétés : pour 4 cartouches, les groupes <strong>Cartouche 1–4</strong> s&#39;affichent ; pour 5, les groupes <strong>Cartouche 1–5</strong>. Les paramètres des cartouches masquées sont conservés et réapparaissent si le nombre total est augmenté.</p><h2 id="eigenes-druckerfoto-und-patronengroße" tabindex="-1">Photo personnalisée de l&#39;imprimante et taille des cartouches <a class="header-anchor" href="#eigenes-druckerfoto-und-patronengroße" aria-label="Permalink to &quot;Photo personnalisée de l&#39;imprimante et taille des cartouches {#eigenes-druckerfoto-und-patronengroße}&quot;">​</a></h2><p>À partir de la version <strong>Studio 0.1.262</strong>, la section <strong>Modèle d&#39;imprimante et image</strong> propose désormais un champ pour saisir un nom de modèle personnalisé, une option pour choisir entre <strong>Graphique standard / Image personnalisée</strong>, ainsi qu&#39;un champ pour la <strong>Photo de votre imprimante (URL ou chemin d&#39;accès local /local/...)</strong>. La saisie d&#39;un chemin d&#39;accès active automatiquement l&#39;affichage de la photo personnalisée ; les URL d&#39;images sans extension de fichier sont également prises en charge. Par ailleurs, la fonction <strong>Importer une image</strong> permet d&#39;ajouter directement au projet un fichier au format PNG, JPEG, WebP, GIF ou SVG (jusqu&#39;à 2 Mo). Les images importées sont intégrées au projet enregistré. Dans le cas d&#39;URL ou de chemins d&#39;accès de type <code>/local/...</code>, la source de l&#39;image doit rester accessible lors de l&#39;exécution (runtime).</p><p>La photo est ajustée proportionnellement. En l&#39;absence d&#39;image ou en cas d&#39;erreur de chargement, le graphique standard s&#39;affiche. L&#39;état et les cartouches restent actifs, indépendamment de la photo ; l&#39;animation des feuilles est associée au graphique standard. Le paramètre <strong>Taille des cartouches</strong> propose les options <strong>Taille réelle / Demi-taille</strong>, avec <strong>Demi-taille</strong> comme valeur par défaut. Seuls les éléments graphiques sont réduits ; les libellés et les pourcentages conservent leur taille d&#39;origine. Ces paramètres sont disponibles même si le pack imprimante est déjà installé ; aucune réinstallation du pack n&#39;est nécessaire.</p><h2 id="status-und-messwerte" tabindex="-1">État et mesures <a class="header-anchor" href="#status-und-messwerte" aria-label="Permalink to &quot;État et mesures {#status-und-messwerte}&quot;">​</a></h2><p>La langue s&#39;aligne automatiquement sur le paramètre du Studio (<strong>DE/EN</strong>), y compris par reprise automatique depuis Home Assistant. Il n&#39;existe pas de sélection de langue spécifique au widget. Les états, indications et propriétés sont traduits ; en revanche, les libellés personnalisés, les noms de modèles et les messages propres à l&#39;entité restent inchangés.</p><p>Les états « Prêt », « Impression », « Veille », « Avertissement », « Arrêté », « Hors ligne » et « Inconnu » sont détectés à partir des valeurs d&#39;état courantes. Lors d&#39;une impression, une feuille se déplace et le voyant LED clignote. L&#39;option du navigateur relative à la « réduction des animations » permet de désactiver ces effets visuels. Les erreurs et les bourrages papier sont prioritaires ; un simple avertissement de niveau bas n&#39;interrompt pas l&#39;animation d&#39;impression.</p><p>L&#39;éditeur et l&#39;environnement d&#39;exécution (runtime) lisent les mêmes valeurs actuelles provenant de Home Assistant. Les niveaux manquants ou invalides s&#39;affichent sous la forme <strong>—</strong> (et non 0 %). Les valeurs numériques valides sont limitées à une plage de <strong>0 à 100 %</strong>. Lorsque les valeurs sont inférieures ou égales au seuil d&#39;avertissement, la cartouche concernée ainsi que sa valeur sont mises en évidence ; les noms correspondants s&#39;affichent en dessous.</p><h2 id="weboberflache" tabindex="-1">Interface web <a class="header-anchor" href="#weboberflache" aria-label="Permalink to &quot;Interface web {#weboberflache}&quot;">​</a></h2><p><strong>URL de l&#39;interface web (auto = depuis l&#39;imprimante)</strong> affiche un lien <strong>Web ↗</strong>. Une URL saisie manuellement est prioritaire. <code>auto</code> utilise la première adresse HTTP/HTTPS trouvée parmi <code>configuration_url</code>, <code>web_url</code>, <code>url</code>, <code>device_url</code> ou <code>printer_uri</code> de l&#39;entité d&#39;état. Si aucune adresse n&#39;est présente, le lien reste masqué ; aucune recherche d&#39;appareil n&#39;est effectuée. Un champ vide entraîne également le masquage du lien. L&#39;interface web s&#39;ouvre dans un nouvel onglet.</p><h2 id="umfang-dieser-version" tabindex="-1">Contenu de cette version <a class="header-anchor" href="#umfang-dieser-version" aria-label="Permalink to &quot;Contenu de cette version {#umfang-dieser-version}&quot;">​</a></h2><p>Cette première version utilise des entités spécifiquement sélectionnées. Elle ne propose pas de recherche automatique d&#39;appareils ou de cartouches, de gestion des pièces d&#39;usure, de contrôle de prises électriques ni d&#39;impression de test. Toutes les connexions sont en mode lecture seule. La carte originale, disponible séparément, offre des fonctionnalités supplémentaires.</p>',29)])])}const b=r(o,[["render",l]]);export{f as __pageData,b as default};
